import { Card, CardContent } from "@/components/ui/card";
import { prisma } from "@/lib/prisma";
import { requirePageRole } from "@/lib/guards";
import { formatDate } from "@/lib/format";

// Diagnoses and notes written by your doctors. Nothing here is generated by AI.
export default async function PatientDiagnosticsPage() {
  const user = await requirePageRole("PATIENT");
  const owner = { patient: { userId: user.id, deletedAt: null } };

  const [consultations, notes] = await Promise.all([
    prisma.consultation.findMany({
      where: { ...owner, status: "FINALIZED", diagnosis: { not: null } },
      orderBy: { finalizedAt: "desc" },
      take: 30,
      select: { id: true, finalizedAt: true, diagnosis: true, treatmentPlan: true, recommendations: true, doctor: { select: { user: { select: { name: true } } } } },
    }),
    prisma.clinicalNote.findMany({
      where: { ...owner, visibleToPatient: true },
      orderBy: { createdAt: "desc" },
      take: 30,
      select: { id: true, createdAt: true, type: true, content: true, author: { select: { user: { select: { name: true } } } } },
    }),
  ]);

  return (
    <div className="mx-auto max-w-4xl space-y-6 px-4 md:px-0">
      <div>
        <h1 className="text-2xl font-bold">Diagnostics</h1>
        <p className="mt-1 text-sm text-muted-foreground">Diagnoses and notes written by your doctors</p>
      </div>

      {consultations.length === 0 && notes.length === 0 && <p className="text-sm text-muted-foreground">Nothing has been shared with you yet.</p>}

      {consultations.map((c) => (
        <Card key={c.id} className="beeline-card">
          <CardContent className="space-y-1 p-4 text-sm">
            <p className="font-semibold">{c.diagnosis}</p>
            {c.treatmentPlan && <p className="text-muted-foreground">Plan: {c.treatmentPlan}</p>}
            {c.recommendations && <p className="text-muted-foreground">Advice: {c.recommendations}</p>}
            <p className="text-xs text-muted-foreground">
              {c.doctor.user.name}{c.finalizedAt ? ` — ${formatDate(c.finalizedAt)}` : ""}
            </p>
          </CardContent>
        </Card>
      ))}

      {notes.map((n) => (
        <Card key={n.id} className="beeline-card">
          <CardContent className="space-y-1 p-4 text-sm">
            <p className="whitespace-pre-wrap">{n.content}</p>
            <p className="text-xs text-muted-foreground">
              {n.author.user.name} — {formatDate(n.createdAt)}
            </p>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}
